38	export class OrderService {
39	  constructor(private readonly deps: OrderServiceDeps) {}
40	
41	  async placeOrder(command: NewOrder): Promise<Order> {
42	    const { orders, events, payments, clock, ids } = this.deps;
43	
44	    const order = createOrder(command, {
45	      id: ids.nextId(),
46	      placedAt: clock.now().toISOString(),
47	    });
48	
49	    const authorization = await payments.authorize({
50	      orderId: order.id,
51	      customerId: order.customerId,
52	      amountMinor: totalCents(order),
53	      currency: order.currency,
54	    });
55	    if (!authorization.authorized) {
56	      throw new PaymentDeclinedError(order.id, authorization.declineReason ?? "declined by provider");
57	    }
58	
59	    await orders.save(order);
60	    await events.publish(orderPlaced(order));
61	    return order;
62	  }
63	
64	  async getOrder(id: string): Promise<Order> {
65	    const order = await this.deps.orders.findById(id);
66	    if (order === undefined) {
67	      throw new OrderNotFoundError(id);
68	    }
69	    return order;
70	  }
