72	  /** Lists one customer's orders, newest first, one page at a time. */
73	  async listOrders(query: CustomerOrdersQuery): Promise<OrderPage> {
74	    if (query.customerId.trim() === "") {
75	      throw new ValidationError([{ path: "customerId", message: "is required" }]);
76	    }
77	    if (!Number.isInteger(query.limit) || query.limit < 1 || query.limit > MAX_LIST_LIMIT) {
78	      throw new ValidationError([{ path: "limit", message: `must be an integer between 1 and ${MAX_LIST_LIMIT}` }]);
79	    }
80	    // Ask for one extra row to learn whether another page exists.
81	    const rows = await this.deps.orders.findByCustomer({ ...query, limit: query.limit + 1 });
82	    const orders = rows.slice(0, query.limit);
83	    const last = orders.at(-1);
84	    return rows.length > query.limit && last !== undefined
85	      ? { orders, next: { placedAt: last.placedAt, id: last.id } }
86	      : { orders };
87	  }
88	
89	  async cancelOrder(id: string, options: CancelOrderOptions = {}): Promise<Order> {
90	    const { orders, events, clock } = this.deps;
91	
92	    const existing = await this.getOrder(id);
93	    const cancelledAt = clock.now().toISOString();
94	    const cancelled = cancel(existing, cancelledAt);
95	
96	    await orders.save(cancelled);
97	    await events.publish(orderCancelled(cancelled, cancelledAt, options.reason));
98	    return cancelled;
99	  }
100	}
