11	/**
12	 * Maps a failure to an HTTP response. Domain errors have a stable status and code;
13	 * anything else is an unexpected failure and is reported as a generic 500 without leaking details.
14	 */
15	export function toErrorResponse(error: unknown): HttpResponse {
16	  if (error instanceof ValidationError) {
17	    return errorResponse(400, error.code, "The request is not valid", error.issues);
18	  }
19	  if (error instanceof OrderNotFoundError) {
20	    return errorResponse(404, error.code, error.message);
21	  }
22	  if (error instanceof InvalidStateError) {
23	    return errorResponse(409, error.code, error.message);
24	  }
25	  if (error instanceof PaymentDeclinedError) {
26	    return errorResponse(402, error.code, error.message);
27	  }
28	  if (error instanceof PaymentUnavailableError) {
29	    return errorResponse(502, error.code, "The payment provider is unavailable");
30	  }
31	  if (error instanceof DomainError) {
32	    return errorResponse(422, error.code, error.message);
33	  }
34	  return errorResponse(500, "internal_error", "Unexpected error");
35	}
