1	import { PaymentUnavailableError } from "../core/errors.js";
2	import type { PaymentAuthorization, PaymentAuthorizationRequest, PaymentGateway } from "../core/ports.js";
3	
4	const PAYMENTS_BASE_URL = "https://payments.payments.internal";
5	const AUTHORIZATIONS_PATH = "/v1/authorizations";
6	
7	/** Provider answers that mean "refused", as opposed to "something went wrong". */
8	const DECLINE_STATUSES: ReadonlySet<number> = new Set([402, 409, 422]);
9	
10	type FetchFunction = (input: string, init?: RequestInit) => Promise<Response>;
11	
12	export interface HttpPaymentGatewayOptions {
13	  readonly baseUrl?: string;
14	  readonly timeoutMs?: number;
15	  /** Total tries for transport failures and 5xx answers. Safe because the request is idempotent. */
16	  readonly maxAttempts?: number;
17	  readonly retryDelayMs?: number;
18	  /** Replaces the global `fetch`; used by tests so that no network is involved. */
19	  readonly fetchFunction?: FetchFunction;
20	}
21	
22	/**
23	 * Payments API client.
24	 * 2xx -> authorized; 402/409/422 -> declined (a normal result); anything else -> unavailable.
25	 * The order id is sent as the idempotency key, so a retried request cannot authorize twice.
26	 */
27	export class HttpPaymentGateway implements PaymentGateway {
28	  private readonly baseUrl: string;
29	  private readonly timeoutMs: number;
30	  private readonly maxAttempts: number;
31	  private readonly retryDelayMs: number;
32	  private readonly fetchFunction: FetchFunction | undefined;
33	
34	  constructor(options: HttpPaymentGatewayOptions = {}) {
35	    this.baseUrl = options.baseUrl ?? PAYMENTS_BASE_URL;
36	    this.timeoutMs = options.timeoutMs ?? 5_000;
37	    this.maxAttempts = Math.max(1, options.maxAttempts ?? 2);
38	    this.retryDelayMs = options.retryDelayMs ?? 100;
39	    this.fetchFunction = options.fetchFunction;
40	  }
41	
42	  async authorize(request: PaymentAuthorizationRequest): Promise<PaymentAuthorization> {
43	    let lastFailure: PaymentUnavailableError | undefined;
44	    for (let attempt = 1; attempt <= this.maxAttempts; attempt += 1) {
45	      if (attempt > 1 && this.retryDelayMs > 0) {
46	        await new Promise((resolve) => setTimeout(resolve, this.retryDelayMs * (attempt - 1)));
47	      }
48	      try {
49	        return await this.sendOnce(request);
50	      } catch (error) {
51	        if (!(error instanceof PaymentUnavailableError)) {
52	          throw error;
53	        }
54	        lastFailure = error;
55	      }
56	    }
57	    throw lastFailure ?? new PaymentUnavailableError("Payments API request failed");
58	  }
59	
60	  private async sendOnce(request: PaymentAuthorizationRequest): Promise<PaymentAuthorization> {
61	    const send = this.fetchFunction ?? globalThis.fetch;
62	    let response: Response;
63	    try {
64	      response = await send(`${this.baseUrl}${AUTHORIZATIONS_PATH}`, {
65	        method: "POST",
66	        headers: { "content-type": "application/json", "idempotency-key": request.orderId },
67	        body: JSON.stringify({
68	          orderId: request.orderId,
69	          customerId: request.customerId,
70	          amountMinor: request.amountMinor,
71	          currency: request.currency,
72	        }),
73	        signal: AbortSignal.timeout(this.timeoutMs),
74	      });
75	    } catch (cause) {
76	      throw new PaymentUnavailableError("Payments API request failed", { cause });
77	    }
78	
79	    if (DECLINE_STATUSES.has(response.status)) {
80	      return { authorized: false, declineReason: await readReason(response) };
81	    }
82	    if (!response.ok) {
83	      throw new PaymentUnavailableError(`Payments API answered ${response.status}`);
84	    }
85	    const body = await readJson(response);
86	    if (body.status === "declined") {
87	      return { authorized: false, declineReason: stringOr(body.reason, "declined by provider") };
88	    }
89	    return typeof body.authorizationId === "string"
90	      ? { authorized: true, reference: body.authorizationId }
91	      : { authorized: true };
92	  }
93	}
94	
95	async function readReason(response: Response): Promise<string> {
96	  const body = await readJson(response);
97	  return stringOr(body.reason, `provider answered ${response.status}`);
98	}
99	
100	/** Best-effort JSON read: an empty or non-JSON body is treated as an empty object. */
101	async function readJson(response: Response): Promise<Record<string, unknown>> {
102	  try {
103	    const parsed: unknown = await response.json();
104	    return typeof parsed === "object" && parsed !== null ? (parsed as Record<string, unknown>) : {};
105	  } catch {
106	    return {};
107	  }
108	}
109	
110	function stringOr(value: unknown, fallback: string): string {
111	  return typeof value === "string" && value.length > 0 ? value : fallback;
112	}
